import { NextResponse } from "next/server";

export const runtime = "nodejs";

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const name = typeof body.name === "string" ? body.name.trim() : "";
    const contact = typeof body.contact === "string" ? body.contact.trim() : "";
    const message = typeof body.message === "string" ? body.message.trim() : "";
    const visibility = body.visibility === "website" ? "website" : body.visibility === "email" ? "email" : null;

    if (name.length < 2 || name.length > 100 || message.length < 5 || message.length > 2000 || !visibility || contact.length > 160) {
      return NextResponse.json({ error: "Please check your name, message, and sharing preference." }, { status: 400 });
    }

    const apiKey = process.env.RESEND_API_KEY;
    const from = process.env.RESEND_FROM_EMAIL;
    if (!apiKey || !from) {
      return NextResponse.json({ error: "Guestbook email isn't configured yet. Please contact the couple directly for now." }, { status: 503 });
    }

    const emailText = [
      `New wedding guestbook message from ${name}`,
      "",
      `Contact: ${contact || "Not provided"}`,
      `Website display choice: ${visibility === "website" ? "Guest chose to display this message publicly" : "Private — email only"}`,
      "",
      "Message:",
      message,
    ].join("\n");

    const resendResponse = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        from,
        to: ["oisegideon@gmail.com"],
        subject: `Wedding guestbook message from ${name}`,
        text: emailText,
        reply_to: contact.includes("@") ? contact : undefined,
      }),
    });

    if (!resendResponse.ok) {
      return NextResponse.json({ error: "We couldn't deliver your message by email. Please try again shortly." }, { status: 502 });
    }
    return NextResponse.json({ ok: true });
  } catch {
    return NextResponse.json({ error: "Unable to process your message right now. Please try again." }, { status: 500 });
  }
}
